// Generated by standalone_build.py from desktop/shared/helper.js
import {openOverlay,terminals,notify} from 'herdr';
import {leadFor} from './scope.js';
// Freeze the originating pane, not whichever lane happens to be focused later.
export function askHelper(context, evidence, preset='investigate-failure'){
 if(!['studio','work'].includes(context?.role)){notify({title:'Select a Studio or Work lead',body:'Helpers do not create more helpers.',level:'warning'});return;}
 if(!context?.cwd||!context?.stream||!evidence?.text?.trim()){
  notify({title:'Choose evidence first',body:'Open a file, diff, test result, report or Docker logs.',level:'warning'});return;
 }
 const lead=leadFor(terminals(),context);
 if(!lead){notify({title:'Open the lead conversation first',body:'The helper needs a Studio or Work parent in this stream.',level:'warning'});return;}
 const points=Array.from(evidence.text),limit=18000;
 const clipped=points.length>limit;
 const snapshot={version:1,pane:evidence.pane,cwd:context.cwd,stream:context.stream,
  parent:lead.address.split('/').pop(),source:String(evidence.source||evidence.pane).slice(0,1000),
  captured_at:new Date().toISOString(),text:(evidence.pane==='docker'?points.slice(-limit):points.slice(0,limit)).join(''),
  truncated:clipped||!!evidence.truncated,draft:!!evidence.draft,
  ...(evidence.head?{head:String(evidence.head)}:{}),...(evidence.observed_at?{observed_at:String(evidence.observed_at)}:{})};
 openOverlay({mod:'repo-helper',kind:'dialog',width:780,height:760,props:{context:{...context},snapshot,preset,agent:lead.labels?.['repo-tools.agent']==='cursor'?'cursor':'codex'}});
}
